import io
import logging

import paramiko

from taf.internal.managedobject import ManagedObject
from taf.transport.ssh.connection import ProxySSHConnection, SSHConnection
from taf.transport.ssh.proxy_keys import KeyFetcher

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BaseManagedSshConnection(ManagedObject):
    """
    ManagedObject interface for SSHConnection/ProxySSHConnection.

    - Create SSHConnection or ProxySSHConnection as delegate depending on the
     presence of a proxy.
    - Configure the delegate in constructor.
    - Map setup()/teardown() to connect()/disconnect().
    - Log setup/teardown.
    """

    def __init__(
            self, host, user, port=None, proxy=None, channel_timeout=None,
            **kwargs
    ):
        super(BaseManagedSshConnection, self).__init__(**kwargs)
        self._host = host
        self._port = port
        self._user = user
        self._proxy = proxy
        self._channel_timeout = channel_timeout
        if proxy is not None:
            self.add_prerequisite(proxy)
        self._ssh_connection = self._create_ssh_connection()
        params = {
            k: v
            for k, v in {"hostname": self._host,
                         "port": self._port,
                         "username": self._user}.items()
            if v is not None}
        if self._proxy is not None:
            params["proxy"] = self._proxy.ssh_connection
        params["password"] = None
        self._ssh_connection.configure(**params)

    @property
    def channel_timeout(self):
        return self._channel_timeout

    @property
    def ssh_connection(self):
        return self._ssh_connection

    @property
    def user(self):
        return self._ssh_connection.params["username"]

    @property
    def host(self):
        return self._ssh_connection.params["hostname"]

    def _create_ssh_connection(self):
        if self._proxy:
            return ProxySSHConnection()
        else:
            return SSHConnection()

    def __getattr__(self, name):
        if name in self._ssh_connection.params:
            return self._ssh_connection.params[name]
        else:
            return getattr(self._ssh_connection, name)

    def _get_connection_info(self):
        return "{host!r}:{port!r} as {user!r}".format(
            host=self._host, port=self._port, user=self._user
        )

    def _setup(self):
        logger.debug(
            "connecting to {connection_info}".format(
                connection_info=self._get_connection_info()
            )
        )
        self._ssh_connection.connect()

    def _teardown(self):
        logger.debug(
            "disconnecting from {connection_info}".format(
                connection_info=self._get_connection_info()
            )
        )
        self._ssh_connection.disconnect()


class ManagedSshConnection(BaseManagedSshConnection):

    def __init__(self, password=None, **kwargs):
        """
        Create an SshConnection using password-authentication or
        publickey-authentication with local key files.

        :param str host: host or IP host
        :param str user: user name
        :param str password: password
        :param int port: port
        :param ManagedSSHConnection proxy: underlying SSH connection to
          intermediate host
        """

        super(ManagedSshConnection, self).__init__(**kwargs)
        self._password = password
        self._ssh_connection.configure(password=password)

    def _get_connection_info(self):
        return super(
            ManagedSshConnection, self
        )._get_connection_info() + ":{password!r}".format(
            password=self._password)


class PrivateKeyManagedSshConnection(BaseManagedSshConnection):

    def __init__(self, private_key, **kwargs):
        """
        Create an SshConnection using private_key-authentication.

        :param str host: host or IP host
        :param str user: user name
        :param int port: port
        :param str private_key: private key. It is the format of the
                                ~/.ssh/id_rsa file content, e. g.:
                                    -----BEGIN RSA PRIVATE KEY-----
                                    MIIEpAIBAAKCAQEA6umMSj85oD1gChl/hRHfaosEdgE
                                    ...
                                    qvNQGO2WDkWtvykMTtWQbrFoGTo/t8mZq6ODirENvH/
                                    -----END RSA PRIVATE KEY-----

        :param ManagedSSHConnection proxy: underlying SSH connection to
                                           intermediate host
        """
        super(PrivateKeyManagedSshConnection, self).__init__(**kwargs)
        self._private_key = private_key
        self._pkey = paramiko.RSAKey.from_private_key(
            io.StringIO(self._private_key))
        self._ssh_connection.configure(pkey=self._pkey)

    @property
    def private_key(self):
        return self._private_key

    def _get_connection_info(self):
        return super(
            PrivateKeyManagedSshConnection, self
        )._get_connection_info() + ":PRIVATE_KEY\n{private_key!r}".format(
            private_key=self.private_key
        )


class KeyFetcherManagedSshConnection(BaseManagedSshConnection):

    def __init__(self, managed_key_fetcher, **kwargs):
        """
        Create an SshConnection using private_key from KeyFetcher.

        :param str host: host or IP host
        :param str user: user name
        :param int port: port
        :param ManagedKeyFetcher managed_key_fetcher: ManagedKeyFetcher
                                                      instance.

        :param ManagedSSHConnection proxy: underlying SSH connection to
                                           intermediate host
        """
        super(KeyFetcherManagedSshConnection, self).__init__(**kwargs)
        self._pkey = None
        self._managed_key_fetcher = managed_key_fetcher
        self.add_prerequisite(managed_key_fetcher)

    @property
    def private_key(self):
        return self._managed_key_fetcher.private_key

    def _get_connection_info(self):
        return super(
            KeyFetcherManagedSshConnection, self
        )._get_connection_info() + (":PRIVATE_KEY from KeyFetcher\n"
                                    "{private_key!r}").format(
            private_key=self.private_key
        )

    def _setup(self):
        self._pkey = paramiko.RSAKey.from_private_key(
            io.StringIO(self._managed_key_fetcher.private_key)
        )
        self._ssh_connection.configure(pkey=self._pkey)
        super(KeyFetcherManagedSshConnection, self)._setup()


class ManagedKeyFetcher(ManagedObject):
    def __init__(
            self, managed_ssh_connection, target_host, password=None,
            timeout=None, **kwargs
    ):
        """
        Create an managed KeyFetcher.
        """
        super(ManagedKeyFetcher, self).__init__(**kwargs)
        self._target_host = target_host
        self._password = password
        self._timeout = timeout
        self._private_key = None
        self._managed_ssh_connection = managed_ssh_connection
        self.add_prerequisite(managed_ssh_connection)

    @property
    def private_key(self):
        return self._private_key

    def _setup(self):
        pkey = KeyFetcher.fetch_keys(
            connection=self._managed_ssh_connection.ssh_connection,
            target_host=self._target_host,
            password=self._password,
            timeout=self._timeout,
        )[0]
        io_buffer = io.StringIO()
        pkey.write_private_key(io_buffer)
        self._private_key = io_buffer.getvalue()
